#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long multiply(long long a[][2], long long b[][2]) {
    long long res[2][2] = {{0, 0}, {0, 0}};
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            long long sum = 0;
            for (int k = 0; k < 2; k++) {
                sum += a[i][k] * b[k][j];
            }
            res[i][j] = sum % MOD;
        }
    }
    return res;
}

void matrixExponentiation(long long base[2][2], int exp, long long result[2][2]) {
    if (exp == 1) {
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                result[i][j] = base[i][j];
            }
        }
        return;
    }
    long long half[2][2];
    matrixExponentiation(base, exp / 2, half);
    long long temp[2][2];
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            temp[i][j] = 0;
        }
    }
    long long squared[2][2];
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            squared[i][j] = 0;
        }
    }
    // multiply half * half
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            long long sum = 0;
            for (int k = 0; k < 2; k++) {
                sum += half[i][k] * half[k][j];
            }
            squared[i][j] = sum % MOD;
        }
    }
    if (exp % 2 == 0) {
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                result[i][j] = squared[i][j];
            }
        }
    } else {
        // multiply squared * base
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                long long sum = 0;
                for (int k = 0; k < 2; k++) {
                    sum += squared[i][k] * base[k][j];
                }
                result[i][j] = sum % MOD;
            }
        }
    }
}

long long pow_mod(long long base, int exp) {
    long long res = 1;
    long long cur = base;
    int e = exp;
    while (e > 0) {
        if (e & 1) {
            res = (res * cur) % MOD;
        }
        cur = (cur * cur) % MOD;
        e >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, l, r;
